package com.honorablemobile
import org.junit.Assert.*
import org.junit.Test
import kotlin.random.Random
class VideoPlaybackExcerptTest {
 private fun clips()=listOf(VideoSegment(1000,5000,speed=2f),VideoSegment(500,4500,speed=.5f,sourceId="other"),VideoSegment(5000,8000,speed=1.5f))
 @Test fun crossesSourcesAndSpeedsWithoutReorderingOrRepeatingFootage(){val r=VideoPlaybackExcerpt.prepare(clips(),"1","11");assertEquals(listOf(3000L to 5000L,500L to 4500L,5000L to 6500L),r.clips.map{it.startMs to it.endMs});assertEquals(listOf("primary","other","primary"),r.clips.map{it.sourceId});assertEquals(listOf(0,1,2),r.pieces.map{it.originalIndex});assertEquals(12000000L,r.beforeUs);assertEquals(10000000L,r.afterUs);assertEquals(1000000L,r.pieces.first().originalFromUs);assertEquals(11000000L,r.pieces.last().originalToUs)}
 @Test fun exactBoundariesKeepFullInteriorClipObject(){val c=clips();val r=VideoPlaybackExcerpt.prepare(c,"2","10");assertEquals(1,r.clips.size);assertSame(c[1],r.clips[0]);assertEquals(8000000L,r.afterUs)}
 @Test fun inwardSourceRoundingReportsActualEdges(){val c=listOf(VideoSegment(0,1001,speed=1.5f));val r=VideoPlaybackExcerpt.prepare(c,"0.101","0.501");assertEquals(152L,r.clips[0].startMs);assertEquals(751L,r.clips[0].endMs);assertEquals(101333L,r.pieces[0].originalFromUs);assertEquals(500666L,r.pieces[0].originalToUs);assertEquals(399333L,r.afterUs);assertTrue(r.pieces[0].originalFromUs>=r.requestedFromUs);assertTrue(r.pieces[0].originalToUs<=r.effectiveToUs)}
 @Test fun lastFractionalMillisecondClipsToActualProjectEndWithoutLosingSourceEnd(){val c=listOf(VideoSegment(0,1001,speed=1.5f));val r=VideoPlaybackExcerpt.prepare(c,"0.1","0.668");assertEquals(668000L,r.requestedToUs);assertEquals(667333L,r.effectiveToUs);assertEquals(1001L,r.clips[0].endMs);assertEquals(667333L,r.pieces[0].originalToUs);assertThrows(IllegalArgumentException::class.java){VideoPlaybackExcerpt.prepare(c,"0.1","0.669")}}
 @Test fun fullTinyClipsStayWhileNewTinyEdgeFragmentsAreRefused(){val tiny=VideoSegment(0,10);val c=listOf(VideoSegment(0,1000),tiny,VideoSegment(0,1000));val r=VideoPlaybackExcerpt.prepare(c,"0.5","1.510");assertSame(tiny,r.clips[1]);assertEquals(1010000L,r.afterUs);assertSame(tiny,VideoPlaybackExcerpt.prepare(listOf(tiny,VideoSegment(0,1000)),"0","0.010").clips[0]);assertThrows(IllegalArgumentException::class.java){VideoPlaybackExcerpt.prepare(listOf(tiny,VideoSegment(0,1000)),"0.005","0.010")}}
 @Test fun minimumEdgeDurationIsCheckedAfterInwardRounding(){val c=listOf(VideoSegment(0,1000,speed=1.5f));assertThrows(IllegalArgumentException::class.java){VideoPlaybackExcerpt.prepare(c,"0.101","0.201")};assertTrue(VideoPlaybackExcerpt.prepare(c,"0.101","0.202").afterUs>=100000)}
 @Test fun captionsKeepIntersectionsSourceTimesProvenanceAndAllAppearance(){val a=VideoCaption(500,1500,"Before");val crossing=VideoCaption(1500,2500,"Cross");val after=VideoCaption(3500,4500,"After");val c=VideoSegment(0,5000,title="Keep",volume=.3f,fadeEdges=true,audioFade=true,grade=VideoGrade(exposure=.5f),layout=VideoLayout(rotation=90),titleStyle=VideoTitleStyle(size=.08f),captions=listOf(a,crossing,after),captionSourceUri="content://synthetic/subtitles",motion=VideoMotion(enabled=true,endZoom=1.5f,anchorEndMs=5000));val r=VideoPlaybackExcerpt.prepare(listOf(c),"2","3");assertEquals(c.copy(startMs=2000,endMs=3000,captions=listOf(crossing)),r.clips[0]);assertEquals(listOf(a,crossing,after),c.captions)}
 @Test fun invalidSyntaxOrderingOutsideTimesAndWholeTimelineNoopFailAtomically(){val c=clips();for((a,b)in listOf("" to "1","-1" to "1","1e0" to "2","1.0001" to "2","1" to "1","2" to "1","12" to "13","0" to "12.001","0" to "12","0.01" to "0.02"))assertThrows(Exception::class.java){VideoPlaybackExcerpt.prepare(c,a,b)};assertEquals(clips(),c)}
 @Test fun unsupportedWholeTimelineBoundsAndEmptyInputsFail(){assertThrows(IllegalArgumentException::class.java){VideoPlaybackExcerpt.prepare(emptyList(),"0","1")};assertThrows(IllegalArgumentException::class.java){VideoPlaybackExcerpt.prepare(List(1001){VideoSegment(0,1000)},"0","1")};assertThrows(IllegalArgumentException::class.java){VideoPlaybackExcerpt.prepare(listOf(VideoSegment(0,Int.MAX_VALUE.toLong(),speed=.5f)),"0","1")}}
 @Test fun randomIntervalsMatchIndependentIntegerRateProjection(){val rng=Random(138);var checked=0;repeat(150){val c=List(3){i->VideoSegment(i*6000L,i*6000L+5000,speed=listOf(.5f,1f,1.5f,2f)[rng.nextInt(4)])};val total=VideoPlaybackTime.durationUs(c);val from=rng.nextLong(0,total/1000-2000);val to=rng.nextLong(from+1000,total/1000+1);val expected=mutableListOf<Pair<Long,Long>>();var offset=0L;var valid=true;for(clip in c){val end=offset+clip.durationUs;val lo=maxOf(from*1000,offset);val hi=minOf(to*1000,end);if(lo<hi){val rate=(clip.speed*2).toLong();val a=if(lo==offset)clip.startMs else clip.startMs+((lo-offset)*rate+1999)/2000;val b=if(hi==end)clip.endMs else clip.startMs+(hi-offset)*rate/2000;if((lo!=offset||hi!=end)&&(b-a)*2000<100000*rate)valid=false;expected+=a to b};offset=end};if(valid){val r=VideoPlaybackExcerpt.prepare(c,"${from/1000}.${(from%1000).toString().padStart(3,'0')}","${to/1000}.${(to%1000).toString().padStart(3,'0')}");assertEquals(expected,r.clips.map{it.startMs to it.endMs});assertTrue(r.afterUs<=r.effectiveToUs-r.requestedFromUs);assertTrue(r.pieces.first().originalFromUs>=r.requestedFromUs);assertTrue(r.pieces.last().originalToUs<=r.effectiveToUs);checked++}};assertTrue(checked>=100)}
 @Test fun actualProjectSingleUndoRedoKeepsSoundtrackSettingsAndCodec(){val c=clips();val p=VideoEditProject(10000);val music=VideoSoundtrack("content://synthetic/music",20000,loop=false,startMs=1000,endMs=19000);p.restore(c,mapOf("other" to 5000L),music);val r=VideoPlaybackExcerpt.prepare(c,"1","11",music);val request=VideoBatchReview(c,music);val stage=Any();request.open(stage);request.propose(stage,r.clips);assertTrue(request.apply(stage,p){});assertEquals(music,p.soundtrack);assertTrue(p.undo());assertEquals(c,p.segments);assertFalse(p.canUndo);assertTrue(p.redo());val draft=VideoDraft(10000,p.segments,0,3000,3000,5000,listOf(VideoSource("other","content://synthetic/other",5000)),music);assertEquals(draft,VideoDraftCodec.decode(VideoDraftCodec.encode(draft),10000));assertFalse(request.apply(stage,p){})}
 @Test fun hiddenForeignPausedAndChangedApprovalCannotKeepStaleExcerpt(){for(mode in 0..3){val p=VideoEditProject(10000);val c=clips();p.restore(c,mapOf("other" to 5000L));val request=VideoBatchReview(c,null);val stage=Any();request.open(stage);request.propose(stage,VideoPlaybackExcerpt.prepare(c,"1","11").clips);when(mode){0->{request.dismiss(stage);assertFalse(request.apply(stage,p){})};1->assertFalse(request.apply(Any(),p){});2->assertThrows(IllegalStateException::class.java){request.apply(stage,p){error("paused")}};3->{p.setTitle(0,"Changed");assertThrows(IllegalArgumentException::class.java){request.apply(stage,p){}}}};assertEquals(3,p.segments.size);assertEquals(1000L,p.segments[0].startMs)}}
}
